400	/// List records in a collection, in MST (lexicographic by rkey) order, with cursor pagination.
401	///
402	/// - `limit` caps the number of records returned (the caller is responsible for clamping it
403	///   to any policy bounds).
404	/// - `cursor`, when present, is an rkey from a previous page; only records *after* it in the
405	///   current traversal direction are returned.
406	/// - `reverse` walks the collection in descending rkey order instead of ascending.
407	///
408	/// The returned `cursor` is the last rkey of the page, set only when more records remain.
409	pub async fn list_records_json<S>(
410	    repo: &mut Repository<S>,
411	    collection: &str,
412	    limit: usize,
413	    cursor: Option<&str>,
414	    reverse: bool,
415	) -> Result<ListRecordsPage, RecordError>
416	where
417	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
418	{
419	    use futures::StreamExt;
420	
421	    // The MST key for a record is `<collection>/<rkey>`; the trailing slash confines the
422	    // prefix scan to this exact collection (so `app.bsky.feed.post` won't match
423	    // `app.bsky.feed.postx`).
424	    let prefix = format!("{collection}/");
425	    let strip = |key: &str| key.strip_prefix(&prefix).unwrap_or(key).to_string();
426	
427	    // Collect up to `limit + 1` post-cursor entries — the extra one tells us whether more
428	    // records remain (and thus whether to emit a cursor) without reading the whole page.
429	    let want = limit.saturating_add(1);
430	    let mut entries: Vec<(String, Cid)> = Vec::new();
431	    {
432	        let mut tree = repo.tree();
433	        let mut stream = Box::pin(tree.entries_prefixed(&prefix));
434	
435	        if reverse {
436	            // `entries_prefixed` only yields ascending order and atrium-repo exposes no
437	            // reverse traversal, so descending order requires materializing the collection
438	            // and walking it backwards. Cursor/limit are then applied while walking.
439	            let mut all: Vec<(String, Cid)> = Vec::new();
440	            while let Some(res) = stream.next().await {
441	                let (key, cid) =
442	                    res.map_err(|e| RecordError::Repo(format!("list entries: {e}")))?;
443	                all.push((strip(&key), cid));
444	            }
445	            for (rkey, cid) in all.into_iter().rev() {
446	                if cursor.is_some_and(|c| rkey.as_str() >= c) {
447	                    continue;
448	                }
449	                entries.push((rkey, cid));
450	                if entries.len() == want {
451	                    break;
452	                }
453	            }
454	        } else {
455	            // Ascending: skip up to and including the cursor, then take `limit + 1` and stop.
456	            // Memory and block reads stay proportional to the page, not the collection.
457	            while let Some(res) = stream.next().await {
458	                let (key, cid) =
459	                    res.map_err(|e| RecordError::Repo(format!("list entries: {e}")))?;
460	                let rkey = strip(&key);
461	                if cursor.is_some_and(|c| rkey.as_str() <= c) {
462	                    continue;
463	                }
464	                entries.push((rkey, cid));
465	                if entries.len() == want {
466	                    break;
467	                }
468	            }
469	        }
470	    }
471	
472	    // The (limit + 1)-th entry, if present, means more records remain past this page.
473	    let has_more = entries.len() > limit;
474	    entries.truncate(limit);
475	
476	    // Resolve each record's value by its MST key. `get_raw_cid` would re-enumerate the
477	    // entire MST per record (atrium walks every entry to prove the CID belongs to the
478	    // repo), making a page O(limit × repo-size) — pathological on a mature repo. We
479	    // already walked the tree to collect `(rkey, cid)`, so a keyed lookup (`get_raw`,
480	    // one tree descent) is both membership-safe and O(log n) per record.
481	    let mut records = Vec::with_capacity(entries.len());
482	    for (rkey, cid) in entries {
483	        let full_key = format!("{prefix}{rkey}");
484	        let value: Option<Ipld> = repo
485	            .get_raw(&full_key)
486	            .await
487	            .map_err(|e| RecordError::Repo(format!("read record block: {e}")))?;
488	        let value = value.ok_or(RecordError::NotFound)?;
489	        records.push(ListedRecord {
490	            rkey,
491	            cid,
492	            value: record_value_to_json(&value)?,
493	        });
494	    }
495	
496	    let cursor = if has_more {
497	        records.last().map(|r| r.rkey.clone())
498	    } else {
499	        None
500	    };
501	
502	    Ok(ListRecordsPage { records, cursor })
503	}
