505	/// List the distinct collection NSIDs present in a repository, in lexicographic order.
506	///
507	/// Walks every MST key (`<collection>/<rkey>`) and collects the unique `<collection>`
508	/// prefixes. An empty repo (genesis, no records) yields an empty list. Used by
509	/// `com.atproto.repo.describeRepo` to report which collections a repo holds.
510	pub async fn list_collections<S>(repo: &mut Repository<S>) -> Result<Vec<String>, RecordError>
511	where
512	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
513	{
514	    use futures::StreamExt;
515	
516	    // MST keys arrive in lexicographic order, and every key for a collection shares the
517	    // `<collection>/` prefix — so any key sorting between two of a collection's keys must
518	    // also carry that prefix. Equal-collection keys are therefore contiguous, and a single
519	    // last-seen comparison dedupes them in O(n) with no intermediate set.
520	    let mut collections: Vec<String> = Vec::new();
521	    let mut tree = repo.tree();
522	    let mut stream = Box::pin(tree.keys());
523	    while let Some(res) = stream.next().await {
524	        let key = res.map_err(|e| RecordError::Repo(format!("list keys: {e}")))?;
525	        // MST keys are `<collection>/<rkey>`; the collection is everything before the
526	        // first slash. Keys without a slash are not valid records and are skipped.
527	        if let Some((collection, _)) = key.split_once('/') {
528	            if collections.last().map(String::as_str) != Some(collection) {
529	                collections.push(collection.to_string());
530	            }
531	        }
532	    }
533	    Ok(collections)
534	}
