536	/// Count the total number of records across all collections in a repository.
537	///
538	/// Walks every MST key (`<collection>/<rkey>`) and counts those that name a record (i.e.
539	/// contain a `/`, the collection/rkey separator). Keys without a slash are not valid records
540	/// and are skipped, mirroring [`list_collections`]. An empty repo (genesis, no records)
541	/// yields 0. Used by the operator usage endpoint to report a repo's record count.
542	pub async fn count_records<S>(repo: &mut Repository<S>) -> Result<usize, RecordError>
543	where
544	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
545	{
546	    use futures::StreamExt;
547	
548	    let mut count = 0usize;
549	    let mut tree = repo.tree();
550	    let mut stream = Box::pin(tree.keys());
551	    while let Some(res) = stream.next().await {
552	        let key = res.map_err(|e| RecordError::Repo(format!("count keys: {e}")))?;
553	        if key.contains('/') {
554	            count += 1;
555	        }
556	    }
557	    Ok(count)
558	}
