608	/// Validate a record's collection (NSID) and record key per the ATProto spec,
609	/// before any repo mutation.
610	///
611	/// - `collection` must be a valid NSID (see [`validate_collection`]): at least three
612	///   dot-separated segments, each 1..=63 chars of `[A-Za-z0-9-]` not hyphen-bounded, the
613	///   first not digit-led and the last a letter followed by letters/digits only.
614	/// - `rkey` must be 1..=512 chars from `[A-Za-z0-9._:~-]`, and not `.` or `..`.
615	pub fn validate_record_path(collection: &str, rkey: &str) -> Result<(), RecordError> {
616	    validate_collection(collection)?;
617	
618	    // Record key: 1..=512 chars from [A-Za-z0-9._:~-], and not "." or "..".
619	    if rkey.is_empty() || rkey.len() > 512 || rkey == "." || rkey == ".." {
620	        return Err(RecordError::InvalidPath(format!(
621	            "invalid record key: {rkey}"
622	        )));
623	    }
624	    if !rkey
625	        .chars()
626	        .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_' | ':' | '~'))
627	    {
628	        return Err(RecordError::InvalidPath(format!(
629	            "record key has invalid characters: {rkey}"
630	        )));
631	    }
632	
633	    Ok(())
634	}
