636	/// Write (create or update) a record in the repository.
637	///
638	/// If the key already exists, the record is updated. If not, it is created.
639	/// The commit is signed with the provided signer.
640	///
641	/// Returns the CID of the new record block.
642	///
643	/// # Usage
644	///
645	/// ```rust,ignore
646	/// use repo_engine::put_record;
647	///
648	/// let mut repo = Repository::open(&mut block_store, root_cid).await?;
649	/// let record_cid = put_record(&mut repo, &signer, "app.bsky.feed.post/abc123", &record_data).await?;
650	/// ```
651	pub async fn put_record<S, T>(
652	    repo: &mut Repository<S>,
653	    signer: &CommitSigner,
654	    key: &str,
655	    data: &T,
656	) -> Result<Cid, RecordError>
657	where
658	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
659	    T: Serialize,
660	{
661	    // Choose create vs update by checking existence first — robust against atrium's
662	    // error message wording (which a string match would couple to).
663	    //
664	    // Probe with a pure MST lookup (key → CID), never by decoding the stored record.
665	    // Decoding into a concrete type (e.g. `serde_json::Value`) fails for any record
666	    // that embeds a CID link (`$link`, CBOR tag 42) or byte string (`$bytes`) —
667	    // `serde_json::Value` cannot represent either — which would make every update of
668	    // a profile-with-avatar or post-with-image return a spurious error.
669	    let exists = get_record_cid(repo, key).await?.is_some();
670	    // Capture the previous commit's rev before the builder borrows the repo mutably, so the
671	    // new commit's rev can be forced strictly greater than it.
672	    let prev_rev = repo.commit().rev();
673	    let (mut commit_builder, cid) = if exists {
674	        repo.update_raw(key, data)
675	            .await
676	            .map_err(|e| RecordError::Repo(format!("update record: {e}")))?
677	    } else {
678	        repo.add_raw(key, data)
679	            .await
680	            .map_err(|e| RecordError::Repo(format!("add record: {e}")))?
681	    };
682	    // Force a strictly-increasing rev (atrium defaults it to the raw wall clock).
683	    commit_builder.rev(next_commit_rev(prev_rev.as_ref())?);
684	
685	    // Sign and finalize the commit.
686	    let sig = signer.sign(&commit_builder.bytes());
687	    commit_builder
688	        .finalize(sig)
689	        .await
690	        .map_err(|e| RecordError::Repo(format!("finalize commit: {e}")))?;
691	
692	    Ok(cid)
693	}
694	
695	/// Return the CID of the record block currently stored at `key`, or `None` if absent.
696	///
697	/// The MST maps each record key directly to its block CID, so this is a single tree
698	/// lookup with no record-block fetch. Used to enforce the `swapRecord`
699	/// optimistic-concurrency precondition without deserializing the record itself.
700	pub async fn get_record_cid<S>(
701	    repo: &mut Repository<S>,
702	    key: &str,
703	) -> Result<Option<Cid>, RecordError>
704	where
705	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
706	{
707	    repo.tree()
708	        .get(key)
709	        .await
710	        .map_err(|e| RecordError::Repo(format!("get record cid: {e}")))
711	}
