713	/// Read a record from the repository.
714	///
715	/// Returns `None` if the key does not exist.
716	///
717	/// # Usage
718	///
719	/// ```rust,ignore
720	/// use repo_engine::get_record;
721	///
722	/// let mut repo = Repository::open(&mut block_store, root_cid).await?;
723	/// let record: Option<MyRecord> = get_record(&mut repo, "app.bsky.feed.post/abc123").await?;
724	/// ```
725	pub async fn get_record<S, T>(repo: &mut Repository<S>, key: &str) -> Result<Option<T>, RecordError>
726	where
727	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
728	    T: DeserializeOwned,
729	{
730	    repo.get_raw(key)
731	        .await
732	        .map_err(|e| RecordError::Repo(format!("get record: {e}")))
733	}
